-- pagos: 95 registros

SET FOREIGN_KEY_CHECKS = 0;
-- movimientos_inventario: 198 registros

-- reclamaciones: 10 registros

ALTER TABLE `autores` AUTO_INCREMENT = 11;
ALTER TABLE `categorias` AUTO_INCREMENT = 15;
ALTER TABLE `empleados` AUTO_INCREMENT = 11;
ALTER TABLE `users` AUTO_INCREMENT = 12;
ALTER TABLE `clientes` AUTO_INCREMENT = 61;
ALTER TABLE `proveedores` AUTO_INCREMENT = 6;
ALTER TABLE `zonas_envio` AUTO_INCREMENT = 22;
ALTER TABLE `cupones` AUTO_INCREMENT = 4;
ALTER TABLE `productos` AUTO_INCREMENT = 51;
ALTER TABLE `compras` AUTO_INCREMENT = 13;
ALTER TABLE `detalle_compras` AUTO_INCREMENT = 13;
ALTER TABLE `cierres_caja` AUTO_INCREMENT = 96;
ALTER TABLE `ventas` AUTO_INCREMENT = 112;
ALTER TABLE `detalle_ventas` AUTO_INCREMENT = 128;
ALTER TABLE `pagos` AUTO_INCREMENT = 96;
ALTER TABLE `movimientos_inventario` AUTO_INCREMENT = 199;
